              "text": "[Document context]\nTitle: LiteLLM lowest latency routing regression tests\nSource: LiteLLM pinned checkout\nPath: /code/litellm/tests/local_testing/test_lowest_latency_routing.py\nWorkspace: task/aisha-24720-fix\n\nprint(router.lowesttpm_logger.get_available_deployments(model_group=\"azure-model\"))\n    print(router.get_available_deployment(model=\"azure-model\"))\n    assert (\n        router.get_available_deployment(model=\"azure-model\")[\"model_info\"][\"id\"] == \"2\"\n    )\n\n# test_router_get_available_deployments()\n\n@pytest.mark.asyncio\nasync def test_router_completion_streaming():\n    messages = [\n        {\"role\": \"user\", \"content\": \"Hello, can you generate a 500 words poem?\"}\n    ]\n    model = \"azure-model\"\n    model_list = [\n        {\n            \"model_name\": \"azure-model\",\n            \"litellm_params\": {\n                \"model\": \"azure/gpt-turbo\",\n                \"api_key\": \"os.environ/AZURE_FRANCE_API_KEY\",\n                \"api_base\": \"https://openai-france-1234.openai.azure.com\",\n                \"rpm\": 1440,\n                \"mock_response\": \"Hello world\",\n            },\n            \"model_info\": {\"id\": 1},\n        },\n        {\n            \"model_name\": \"azure-model\",\n            \"litellm_params\": {\n                \"model\": \"azure/gpt-35-turbo\",\n                \"api_key\": \"os.environ/AZURE_EUROPE_API_KEY\",\n                \"api_base\": \"https://my-endpoint-europe-berri-992.openai.azure.com\",\n                \"rpm\": 6,\n                \"mock_response\": \"Hello world\",\n            },\n            \"model_info\": {\"id\": 2},\n        },\n    ]\n    router = Router(\n        model_list=model_list,\n        routing_strategy=\"latency-based-routing\",\n        set_verbose=False,\n        num_retries=3,\n    )  # type: ignore\n\n### Make 3 calls, test if 3rd call goes to fastest deployment\n\n## CALL 1+2\n    tasks = []\n    response = None\n    final_response = None\n    for _ in range(2):\n        tasks.append(router.acompletion(model=model, messages=messages))\n    response = await asyncio.gather(*tasks)",
